#!/bin/bash
# scratch (2026-11-08 03:50): the judgement columns of E277 (verdict277 by hand, run 03:40) and E278; numbers from runs/e277/<run>/card.json, runs/e278/<run>/card.json (temp/e276/summarise_e277.py, summarise_e278.py)
cd "$(dirname "$0")/../.."
L="python3 ../autoresearch/tools/ledger.py note"
R='head trained with the soft close-node step (radius 1.5 m, smoothness 0.1 m, 3 passes), read at e >= 0.5 with no hard step, seed 0 / seed 1: topo F1 0.621 / 0.624 (baseline 0.597 / 0.595: +0.024 / +0.029; hard step E275 0.626 / 0.625: trail 0.005 / 0.001), junction F1 0.263 / 0.268 (baseline 0.130 / 0.120; hard step 0.271 / 0.249), F1@1.0 0.818 / 0.820 (baseline 0.832 / 0.821: -0.015 / -0.001), lanes found 0.604 / 0.619 (baseline 0.644 / 0.630: -0.039 / -0.011), vertices per 100 m 19.1 / 18.8 (baseline 28.9 / 31.5), node recall 0.787 / 0.790, precision 0.916 / 0.911, duplicates 0.230 / 0.242, long-link precision 0.172 / 0.186; assignment p-g exact -0.0064 / -0.0048, error +0.0736 / +0.0715; the hard step on top of the soft one drops no further node (cards identical)'
D='verdict277 by hand (03:40): CUT by the written guards: seed 0 breaks F1@1.0 (-0.0147 against -0.010) and lanes found (-0.0394 against -0.030); seed 1 holds every guard. Both headline gains hold on both seeds (topo F1 > +0.02, junction F1 > +0.03) and the soft step replaces the hard one (trail 0.005 / 0.001 < 0.01). All five numeric predictions held (topo F1 0.62, junction F1 >= 0.22, lanes found 0.60 - 0.64, vertices per 100 m 18 - 22, exact-map guard). The hard step stays the named read-out; the soft step is a trained thinning that needs no rule step but loses more lane recall on one seed than the guards allow; follow-up E279 (radius 1.25 m, same rule)'
$L E277.u_s0 --result "$R" --decision "$D" --notes 'training 01:12-03:09 (phases 3-7; phase 7 at 1.5 s per step with both seeds on the GPU); the phase-3 gate read the raw head (critic finding after the start: fixed in qgates, the scoring cards judge); the first version of the step with the 1e-6 clamp'
$L E277.u_s1 --result "$R" --decision "$D" --notes 'training 01:19-03:15; same notes as u_s0'
$L E277.uq_s0 --result 'scoring card of the E277 head seed 0 (runs/e277/e277_u_s0.plain_t0.5 and .close1.5_t0.5): numbers in the row of E277.u_s0' --decision 'feeds verdict277 (CUT by the guards)' --notes 'the scheduler left its loop at "every job is done" before it reached the verdict block; verdict277 was run by hand at 03:40 (scheduler fixed: the verdict blocks now come before the exit test)'
$L E277.uq_s1 --result 'scoring card of the E277 head seed 1: numbers in the row of E277.u_s0' --decision 'feeds verdict277 (CUT by the guards)'
P='E278 (diagnostic, scoring only, never a verdict): the phase-6 model of B (before the joint phase 7), read at e >= 0.5, seed 0 / 1 against the final B: topo F1 0.544 / 0.570 (final 0.597 / 0.595), junction F1 0.156 / 0.168 (0.130 / 0.120), lanes found 0.667 / 0.573 (0.644 / 0.630), vertices per 100 m 22.9 / 26.9 (28.9 / 31.5), duplicates 0.407 / 0.270 (0.232 / 0.192), long-link precision 0.097 / 0.155 (0.167 / 0.191); with the hard step: topo F1 0.565 / 0.571 (final + step 0.626 / 0.625), junction F1 0.311 / 0.342 (0.271 / 0.249)'
Q='the joint phase 7 raises topo F1 (+0.03 to +0.05), long-link precision and lowers duplicates; it lowers junction F1 under the hard step (-0.04 / -0.09) and raises the vertices per 100 m; the phase stays (a trade, not a recipe change)'
$L E278.qp_s0 --result "$P" --decision "$Q" --notes 'no card (a diagnostic through run.py --no-card); cards runs/e278/e273_p_s<k>_p6.plain_t0.5 and .close1.5_t0.5'
$L E278.qp_s1 --result "$P" --decision "$Q"
